# These are literal golden byte vectors derived from the Section 9.9 rational
# definition, not generated by the adapter under test.  Keeping them as Base64
# also tests the exact JSON-facing representation.
GOLDEN = {
    "silence-48k": {
        5: (1, "AAAAAAAA"),
        50: (1, "AAAAAAAA"),
        250: (1, "AAAAAAAA"),
    },
    "negative-full-scale-44k1": {
        5: (1, "AIAAgP9/"),
        50: (1, "AIAAgP9/"),
        250: (1, "AIAAgP9/"),
    },
    "stereo-mix-48k": {
        5: (1, "AID/f4Ja"),
        50: (1, "AID/f4Ja"),
        250: (1, "AID/f4Ja"),
    },
    "final-partial-48k": {
        5: (2, "AAAAAAAA/3//f/9/"),
        50: (1, "AAD/fz8I"),
        250: (1, "AAD/fz8I"),
    },
    "final-partial-44k1": {
        5: (2, "AAAAAAAAAIAAgP9/"),
        50: (1, "AIAAACYM"),
        250: (1, "AIAAACYM"),
    },
}


def assert_golden(test: unittest.TestCase, result: dict, name: str) -> None:
    test.assertEqual("complete", result["status"])
    test.assertEqual(ENCODING, result["encoding"])
    test.assertEqual([5, 50, 250], [level["frameDurationMs"] for level in result["levels"]])
    for level in result["levels"]:
        expected_count, expected_data = GOLDEN[name][level["frameDurationMs"]]
        test.assertEqual(expected_count, level["frameCount"])
        test.assertEqual(expected_data, level["data"])
        decoded = base64.b64decode(level["data"], validate=True)
        test.assertEqual(level["frameCount"] * 6, len(decoded))


def write_float_wave(path: Path, samples: np.ndarray, rate: int, *, extensible: bool = False) -> None:
    samples = np.ascontiguousarray(samples, dtype="<f4")
    if samples.ndim == 1:
        samples = samples.reshape(-1, 1)
    channels = samples.shape[1]
    block_align = channels * 4
    if extensible:
        # WAVE_FORMAT_EXTENSIBLE, valid bits, channel mask, IEEE-float subtype.
        fmt = struct.pack(
            "<HHIIHHHHI16s",
            0xFFFE,
            channels,
            rate,
            rate * block_align,
            block_align,
            32,
            22,
            32,
            0,
            bytes.fromhex("0300000000001000800000aa00389b71"),
        )
    else:
        fmt = struct.pack("<HHIIHH", 3, channels, rate, rate * block_align, block_align, 32)
    data = samples.tobytes(order="C")
    body = b"WAVE" + b"fmt " + struct.pack("<I", len(fmt)) + fmt
    body += b"data" + struct.pack("<I", len(data)) + data
    path.write_bytes(b"RIFF" + struct.pack("<I", len(body)) + body)


class WaveformGoldenVectorTests(unittest.TestCase):
    def test_silence_mono_48khz(self) -> None:
        result = waveform_from_samples(np.zeros(3, dtype="<f4"), 48_000)
        assert_golden(self, result, "silence-48k")

    def test_negative_full_scale_mono_44k1(self) -> None:
        result = waveform_from_samples(np.array([-1.0], dtype="<f4"), 44_100)
        assert_golden(self, result, "negative-full-scale-44k1")

    def test_stereo_extrema_and_channel_energy_48khz(self) -> None:
        # All channel samples cover [-1, 1]; two of four samples have unit energy.
        # RMS maps to round(32767/sqrt(2)) = 23170.
        samples = np.array([[1.0, 0.0], [-1.0, 0.0]], dtype="<f4")
        result = waveform_from_samples(samples, 48_000, chunk_frames=1)
        assert_golden(self, result, "stereo-mix-48k")

    def test_final_partial_frame_48khz(self) -> None:
        # The 5 ms boundary at 48 kHz is exactly 240 samples.  Sample 241 must
        # be emitted as a second frame rather than discarded.
        samples = np.concatenate(
            [np.zeros(240, dtype="<f4"), np.ones(1, dtype="<f4")]
        )
        result = waveform_from_samples(samples, 48_000, chunk_frames=137)
        assert_golden(self, result, "final-partial-48k")

    def test_floor_boundaries_and_final_partial_frame_44k1(self) -> None:
        # floor(44100 * 5 / 1000) is 220.  The last two samples belong to the
        # second frame, proving the algorithm does not round the boundary to 221.
        samples = np.concatenate(
            [np.zeros(220, dtype="<f4"), -np.ones(2, dtype="<f4")]
        )
        result = waveform_from_samples(samples, 44_100, chunk_frames=17)
        assert_golden(self, result, "final-partial-44k1")

    def test_canonical_duration_controls_coverage_and_folds_pcm_tail(self) -> None:
        # 2401 samples are 50.0208 ms at 48 kHz, which rounds to the canonical
        # 50 ms timeline. Sample-derived framing used to emit an extra 5 ms and
        # 50 ms frame. The final nonzero sample must instead remain represented
        # in the final declared frame at every level.
        samples = np.zeros(2_401, dtype="<f4")
        samples[-1] = 1.0
        result = waveform_from_samples(
            samples,
            48_000,
            duration_ms=50,
            chunk_frames=317,
        )
        self.assertEqual([10, 1, 1], [level["frameCount"] for level in result["levels"]])
        for level in result["levels"]:
            decoded = base64.b64decode(level["data"], validate=True)
            self.assertEqual(level["frameCount"] * 6, len(decoded))
            _, maximum, _ = struct.unpack("<hhH", decoded[-6:])
            self.assertEqual(32_767, maximum)

    def test_canonical_duration_rejects_foreign_pcm_timeline(self) -> None:
        samples = np.zeros(48_000, dtype="<f4")
        with self.assertRaisesRegex(WaveformError, "differs from PCM duration"):
            waveform_from_samples(samples, 48_000, duration_ms=1_100)

    def test_canonical_duration_accepts_exact_half_ms_rounding_boundary(self) -> None:
        result = waveform_from_samples(
            np.zeros(48_024, dtype="<f4"),
            48_000,
            duration_ms=1_000,
        )
        self.assertEqual([200, 20, 4], [level["frameCount"] for level in result["levels"]])

    def test_canonical_duration_rejects_just_over_half_ms(self) -> None:
        with self.assertRaisesRegex(WaveformError, "more than 0.5 ms"):
            waveform_from_samples(
                np.zeros(48_025, dtype="<f4"),
                48_000,
                duration_ms=1_000,
            )

    def test_exact_binary32_to_q31_edges(self) -> None:
        samples = np.array(
            [-2.0, -1.0, -0.5, -0.0, 0.0, 0.5, 1.0, 2.0], dtype="<f4"
        )
        actual = _float32_bits_to_q31(samples.view("<u4"))
        np.testing.assert_array_equal(
            np.array(
                [
                    -2_147_483_648,
                    -2_147_483_648,
                    -1_073_741_824,
                    0,
                    0,
                    1_073_741_824,
                    2_147_483_647,
                    2_147_483_647,
                ],
                dtype=np.int64,
            ),
            actual,
        )

    def test_every_finite_exponent_matches_scalar_rational_rounding(self) -> None:
        patterns = np.array([
            (sign << 31) | (exponent << 23) | fraction
            for sign in (0, 1)
            for exponent in range(255)
            for fraction in (0, 1, 0x3FFFFF, 0x400000, 0x7FFFFE, 0x7FFFFF)
        ], dtype=np.uint32)
        expected = []
        for pattern in patterns:
            value = int(pattern)
            sign = value >> 31
            exponent = (value >> 23) & 255
            if exponent >= 127:
                rounded = -2_147_483_648 if sign else 2_147_483_647
            else:
                mantissa = (value & 0x7FFFFF) + ((1 << 23) if exponent else 0)
                denominator = 1 << (150 - max(1, exponent))
                rounded = (mantissa * 2_147_483_647 + denominator // 2) // denominator
                if sign:
                    rounded = -rounded
            expected.append(rounded)
        # Also exercises multidimensional, non-contiguous input and an empty selection.
        shaped = patterns.reshape(-1, 2).T
        np.testing.assert_array_equal(
            np.array(expected, dtype=np.int64).reshape(-1, 2).T,
            _float32_bits_to_q31(shaped),
        )
        np.testing.assert_array_equal(
            np.zeros((0, 2), dtype=np.int64),
            _float32_bits_to_q31(np.zeros((0, 2), dtype=np.uint32)),
        )

    def test_square_prefix_ranges_match_unbounded_scalar_sums(self) -> None:
        rng = np.random.default_rng(20260908)
        samples = rng.integers(-2_147_483_648, 2_147_483_648, 513, dtype=np.int64)
        samples[:4] = [-2_147_483_648, 2_147_483_647, -65_535, 65_536]
        for values in (samples, np.full(1_000_000, 2_147_483_647, dtype=np.int64)):
            prefix = _square_sums_prefix(values)
            for start, end in ((0, values.size), (0, 1), (1, 4), (137, 317)):
                high, cross, low = prefix[:, end] - prefix[:, start]
                actual = (int(high) << 32) + (int(cross) << 16) + int(low)
                expected = sum(int(value) ** 2 for value in values[start:end])
                self.assertEqual(expected, actual)

    def test_waveform_reductions_preserve_chunk_and_timeline_boundaries(self) -> None:
        rng = np.random.default_rng(20260908)
        for rate in (44_100, 48_000):
            for channels in (1, 2):
                with self.subTest(rate=rate, channels=channels):
                    # One sample past a whole-second timeline must be folded into
                    # the final frame, including when a chunk ends inside it.
                    samples = rng.uniform(-1.1, 1.1, (rate + 1, channels)).astype("<f4")
                    expected = waveform_from_samples(samples, rate, duration_ms=1000)
                    self.assertEqual(expected, waveform_from_samples(
                        samples, rate, duration_ms=1000, chunk_frames=137
                    ))
        # Cross the internal coefficient-sum bound independently of input chunks.
        samples = np.full((1_000_003, 1), -1.0, dtype="<f4")
        self.assertEqual(
            waveform_from_samples(samples, 48_000, chunk_frames=262_144),
            waveform_from_samples(samples, 48_000, chunk_frames=samples.shape[0]),
        )


class WaveformFileTests(unittest.TestCase):
    def test_reads_ieee_float_wave_without_normalization(self) -> None:
        samples = np.array([[1.0, 0.0], [-1.0, 0.0]], dtype="<f4")
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "canonical.wav"
            write_float_wave(path, samples, 48_000)
            result = build_waveform(path, chunk_frames=1)
        assert_golden(self, result, "stereo-mix-48k")

    def test_file_encoder_uses_canonical_duration(self) -> None:
        samples = np.zeros(2_401, dtype="<f4")
        samples[-1] = 1.0
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "canonical.wav"
            write_float_wave(path, samples, 48_000)
            result = build_waveform(path, duration_ms=50)
        self.assertEqual([10, 1, 1], [level["frameCount"] for level in result["levels"]])

    def test_reads_extensible_ieee_float_wave(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "canonical-extensible.wav"
            write_float_wave(path, np.array([-1.0], dtype="<f4"), 44_100, extensible=True)
            result = build_waveform(path)
        assert_golden(self, result, "negative-full-scale-44k1")

    def test_reads_headerless_f32le_with_explicit_format(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "canonical.f32le"
            path.write_bytes(np.zeros(3, dtype="<f4").tobytes())
            result = build_waveform(path, sample_rate_hz=48_000, channels=1)
        assert_golden(self, result, "silence-48k")

    def test_raw_input_requires_format(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "canonical.f32le"
            path.write_bytes(np.zeros(1, dtype="<f4").tobytes())
            with self.assertRaisesRegex(WaveformError, "requires sample_rate_hz and channels"):
                build_waveform(path)

    def test_nan_and_infinity_fail_the_whole_run(self) -> None:
        for value in (np.nan, np.inf, -np.inf):
            with self.subTest(value=value):
                samples = np.array([[0.0, value]], dtype="<f4")
                with self.assertRaisesRegex(WaveformError, r"frame 0, channel 1"):
                    waveform_from_samples(samples, 48_000)

    def test_empty_pcm_is_rejected(self) -> None:
        with self.assertRaisesRegex(WaveformError, "no sample frames"):
            waveform_from_samples(np.array([], dtype="<f4"), 48_000)


if __name__ == "__main__":
    unittest.main()
